use super::*;
#[test]fn jpeg_orientation_metadata_and_quality(){let d=tempfile::tempdir().unwrap();let src=d.path().join("oriented.jpg");let mut im=image::RgbImage::new(80,40);for(x,y,p)in im.enumerate_pixels_mut(){*p=image::Rgb([(x*3)as u8,(y*6)as u8,((x+y)*2)as u8]);}im.save(&src).unwrap();let mut data=fs::read(&src).unwrap();let exif:[u8;32]=[b'E',b'x',b'i',b'f',0,0,b'I',b'I',42,0,8,0,0,0,1,0,0x12,1,3,0,1,0,0,0,6,0,0,0,0,0,0,0];let mut marker=vec![0xff,0xe1,0,34];marker.extend(exif);data.splice(2..2,marker);fs::write(&src,data).unwrap();let s=Settings{format:"jpeg".into(),output_folder:d.path().to_string_lossy().into(),..Default::default()};let item=preview(vec![src.to_string_lossy().into()],&s).unwrap().remove(0);image_process(&item,&s,&AtomicBool::new(false),&mut|_|{}).unwrap();let out=image::open(&item.output).unwrap();assert_eq!((out.width(),out.height()),(40,80));assert!(!fs::read(&item.output).unwrap().windows(4).any(|b|b==b"Exif"));let mut low=s.clone();low.quality=15;let p=preview(vec![src.to_string_lossy().into()],&low).unwrap().remove(0);image_process(&p,&low,&AtomicBool::new(false),&mut|_|{}).unwrap();assert!(fs::metadata(p.output).unwrap().len()<fs::metadata(item.output).unwrap().len());}
